<?php
require_once __DIR__.'/_doc_helpers.php';
function render_bamab_card(array $x): void {
    $D=bamab_doc_design();
    $frontTitle=bamab_doc_clean_title((string)($x['front_title']??''),'DOCUMENTO BAMAB');
    $name=trim((string)($x['name']??''));
    $preferred=trim((string)($x['preferred']??''));
    $showPref=setting('doc_show_preferred_name','1')==='1' && $preferred!=='' && mb_strtolower($preferred)!==mb_strtolower($name);
    $showFrontQr=setting('doc_show_qr_on_front','1')==='1';
    $showBackQr=setting('doc_show_qr_on_back','1')==='1';
    $showMotto=setting('doc_show_motto','1')==='1';
    $active=(bool)($x['active']??true);
    $studentNameEmphasis=(bool)($x['student_name_emphasis']??false);
    $cardNameSize=min(3.9,$D['cardName']+($studentNameEmphasis?0.30:0.0));
    $frontFields=$x['fields']??[];
    if($showPref && !empty($x['preferred_label'])){
        array_splice($frontFields,1,0,[['label'=>$x['preferred_label'],'value'=>$preferred,'kind'=>'value']]);
    }
    $titleClass=bamab_doc_fit_class($frontTitle,'card-title');
    $nameClass=bamab_doc_fit_class($name,'card-name');
    $backTitle='VERSO — '.$frontTitle;
    $backTitleClass=bamab_doc_fit_class($backTitle,'back-title');
    $backNotice=bamab_doc_safe_text((string)($x['back_notice']??''),750);
    $backNoticeClass=bamab_doc_fit_class($backNotice,'back-text');
    $signatures=$x['signatures']??[];
    $valid=(string)($x['valid']??'—');
    $logo=(string)$x['logo'];$photo=(string)$x['photo'];$qr=(string)$x['qr'];
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e((string)($x['page_title']??$frontTitle))?></title><style>
*{box-sizing:border-box;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}html,body{margin:0}body{background:#d9d9d9;font-family:Arial,"Segoe UI",sans-serif;color:#111;text-rendering:geometricPrecision}.sheet{display:flex;gap:20px;flex-wrap:wrap;justify-content:center;padding:22px}.card{width:85.60mm;height:53.98mm;position:relative;overflow:hidden;border:1.05mm solid <?=$D['wine']?>;border-radius:3.8mm;background:linear-gradient(112deg,<?=$D['dark']?> 0 31%,<?=$D['light']?> 31% 100%);box-shadow:0 8px 22px #0005}.card:before{content:"";position:absolute;inset:1.15mm;border:.4mm solid <?=$D['gold']?>;border-radius:2.7mm;pointer-events:none;z-index:30}.card.inactive:after{content:"DOCUMENTO INATIVO";position:absolute;z-index:40;left:21mm;right:7mm;top:22mm;text-align:center;padding:1.2mm;background:#fff;color:#b00000;border:.7mm solid #b00000;font-size:4.2mm;font-weight:900;transform:rotate(-8deg);box-shadow:0 1mm 2mm #0004}.left{position:absolute;left:2.5mm;top:3mm;width:24mm;text-align:center;color:<?=$D['gold']?>;z-index:2}.left img{width:19.5mm;height:19.5mm;object-fit:contain;filter:drop-shadow(0 1.2mm 1.2mm #0008)}.left b{display:block;font:700 5.1mm Georgia,"Times New Roman",serif;line-height:1}.left small{display:block;font-size:1.55mm;line-height:1.15;letter-spacing:.13mm;margin-top:.7mm}.ribbon{position:absolute;left:-7mm;bottom:5.5mm;width:40mm;height:6.2mm;background:linear-gradient(<?=$D['wine']?>,#350606,<?=$D['wine']?>);transform:rotate(-16deg);border:.25mm solid <?=$D['gold']?>;opacity:.96}.title{position:absolute;left:29mm;right:3.7mm;top:2.8mm;height:7.5mm;display:flex;align-items:center;justify-content:center;text-align:center;padding:0 .7mm;font-family:Georgia,"Times New Roman",serif;font-weight:700;font-size:<?=$D['cardTitle']?>mm;line-height:.98;color:<?=$D['text']?>;overflow:hidden;overflow-wrap:anywhere}.title.fit-sm{font-size:<?=max(2.3,$D['cardTitle']*.88)?>mm}.title.fit-xs{font-size:<?=max(2.2,$D['cardTitle']*.78)?>mm}.title.fit-xxs{font-size:<?=max(2.1,$D['cardTitle']*.70)?>mm}.title.fit-tiny{font-size:2mm}.photo{position:absolute;right:4mm;top:13mm;width:16.5mm;height:22mm;object-fit:cover;object-position:center;border:.55mm solid <?=$D['gold']?>;border-radius:1.6mm;background:#fff}.student-name-band{position:absolute;left:29mm;right:22mm;top:10.7mm;height:9.1mm;border:.38mm solid <?=$D['gold']?>;border-radius:1.8mm;background:linear-gradient(180deg,<?=$D['wine']?>,#3a0808);box-shadow:inset 0 .35mm .6mm #ffffff18,0 .45mm 1mm #0002;padding:.75mm 1.2mm .85mm;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;overflow:hidden;z-index:4}.student-name-band small{display:block;color:#f1d58a;font-size:<?=max(1.25,$D['cardLabel']*.78)?>mm;font-weight:900;line-height:1;letter-spacing:.08mm;margin-bottom:.35mm;text-transform:uppercase}.student-name-band strong{display:flex;align-items:center;justify-content:center;width:100%;min-height:4.8mm;max-height:5.8mm;color:#fff;font-family:Arial,"Segoe UI",sans-serif;font-size:<?=$cardNameSize?>mm;font-weight:950;line-height:.96;white-space:normal;overflow:hidden;text-align:center;overflow-wrap:anywhere;word-break:normal;hyphens:auto;text-shadow:0 .3mm .5mm #0008}.student-name-band strong.fit-sm{font-size:<?=max(2.05,$cardNameSize*.88)?>mm}.student-name-band strong.fit-xs{font-size:<?=max(1.90,$cardNameSize*.78)?>mm}.student-name-band strong.fit-xxs{font-size:<?=max(1.75,$cardNameSize*.69)?>mm}.student-name-band strong.fit-tiny{font-size:1.65mm}.fields{position:absolute;left:29.5mm;right:22mm;top:20.5mm;bottom:3.4mm;display:flex;flex-direction:column;gap:.42mm;overflow:hidden}.field{min-height:0}.field small{display:block;color:<?=$D['wine']?>;font-size:<?=$D['cardLabel']?>mm;font-weight:900;line-height:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.field strong{display:block;border-bottom:.16mm solid <?=$D['gold']?>;padding:.2mm 0 .35mm;font-size:<?=$D['cardField']?>mm;line-height:1.04;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:800}.field strong.fit-sm{font-size:<?=max(1.55,$D['cardField']*.90)?>mm}.field strong.fit-xs{font-size:<?=max(1.48,$D['cardField']*.82)?>mm}.field strong.fit-xxs{font-size:<?=max(1.40,$D['cardField']*.74)?>mm}.field strong.fit-tiny{font-size:1.35mm}.qr{position:absolute;right:4.2mm;bottom:3.8mm;width:12.8mm;height:12.8mm;object-fit:contain;background:#fff;padding:.45mm;border:.38mm solid <?=$D['gold']?>;border-radius:1mm}.motto{position:absolute;left:29mm;right:18mm;bottom:1.8mm;text-align:center;color:<?=$D['gold']?>;font-size:1.35mm;letter-spacing:.08mm;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:800}.back{background:linear-gradient(112deg,<?=$D['dark']?> 0 29%,<?=$D['light']?> 29% 100%)}.back-title{position:absolute;left:30mm;right:4mm;top:3mm;height:7mm;display:flex;align-items:center;justify-content:center;text-align:center;font:700 <?=$D['backTitle']?>mm/1 Georgia,"Times New Roman",serif;color:<?=$D['text']?>;overflow:hidden;overflow-wrap:anywhere}.back-title.fit-sm{font-size:<?=max(2.4,$D['backTitle']*.88)?>mm}.back-title.fit-xs{font-size:<?=max(2.25,$D['backTitle']*.78)?>mm}.back-title.fit-xxs{font-size:2.1mm}.back-title.fit-tiny{font-size:1.95mm}.back-content{position:absolute;left:30.5mm;right:4mm;top:11mm;bottom:3.5mm;display:flex;flex-direction:column;gap:1.1mm;padding-right:0}.notice{border:.3mm solid <?=$D['gold']?>;border-radius:1.7mm;padding:1.6mm 1.8mm;background:#fffffff0;min-height:0;max-height:15.5mm;overflow:hidden}.notice h3{margin:0 0 .8mm;text-align:center;color:<?=$D['wine']?>;font-size:1.9mm;line-height:1}.notice p{margin:0;font-size:<?=$D['backText']?>mm;line-height:1.28;overflow-wrap:anywhere}.notice.fit-sm p{font-size:<?=max(1.25,$D['backText']*.91)?>mm}.notice.fit-xs p{font-size:<?=max(1.20,$D['backText']*.83)?>mm}.notice.fit-xxs p{font-size:1.16mm;line-height:1.22}.notice.fit-tiny p{font-size:1.10mm;line-height:1.18}.signs{display:grid;grid-template-columns:repeat(<?=max(1,count($signatures))?>,1fr);gap:1.3mm}.sig{height:8.1mm;border:.22mm solid <?=$D['gold']?>;border-radius:1.4mm;background:#fffffff0;padding:.8mm;text-align:center;overflow:hidden}.sig small{display:block;font-size:1.35mm;line-height:1.05;color:<?=$D['wine']?>;font-weight:900;white-space:normal}.sig div{border-bottom:.16mm solid #666;margin-top:3.2mm}.back-bottom{margin-top:auto;display:flex;align-items:flex-end;min-height:11.6mm;padding-right:14.8mm}.back-valid{font-size:1.55mm}.back-valid small{display:block;color:#555;font-weight:800}.back-valid strong{display:block;font-size:2.4mm;color:<?=$D['text']?>}.back-qr{position:absolute;right:0;bottom:0;width:12.8mm;height:12.8mm;object-fit:contain;background:#fff;padding:.45mm;border:.38mm solid <?=$D['gold']?>;border-radius:1mm}.buttons{width:100%;display:flex;gap:8px;justify-content:center;flex-wrap:wrap}.buttons button{padding:11px 16px;font-weight:900;border:1px solid #333;border-radius:7px;background:#111;color:#fff;cursor:pointer}.note{width:100%;text-align:center;font-size:12px;color:#444}.note strong{color:#8a5d00}
@media print{html,body{width:85.60mm!important;margin:0!important;padding:0!important;background:#fff!important}.sheet{padding:0!important;display:block!important;width:85.60mm!important}.card{width:85.60mm!important;height:53.98mm!important;box-shadow:none!important;margin:0!important;break-after:page;page-break-after:always}.card:last-of-type{break-after:auto;page-break-after:auto}.buttons,.note{display:none!important}body.print-front .back-card{display:none!important}body.print-front .front-card{break-after:auto!important;page-break-after:auto!important}body.print-back .front-card{display:none!important}body.print-back .back-card{break-after:auto!important;page-break-after:auto!important}@page{size:85.60mm 53.98mm;margin:0}}
</style></head><body><div class="sheet">
<section class="card front-card <?=$active?'':'inactive'?>"><div class="left"><img src="<?=e($logo)?>" alt="Brasão BAMAB"><b>BAMAB</b><small>BANDA AMARAL BRASIL</small></div><div class="ribbon"></div><div class="title <?=$titleClass?>"><?=e($frontTitle)?></div><img class="photo" src="<?=e($photo)?>" alt="Foto" onerror="this.onerror=null;this.src='<?=e($logo)?>';"><div class="student-name-band"><small><?=e((string)($x['name_label']??'NOME'))?></small><strong class="<?=$nameClass?>"><?=e($name?:'—')?></strong></div><div class="fields"><?php foreach($frontFields as $f):$value=(string)($f['value']??'');$fit=bamab_doc_fit_class($value,'card-value');?><div class="field"><small><?=e((string)($f['label']??''))?></small><strong class="<?=$fit?>"><?=e($value!==''?$value:'—')?></strong></div><?php endforeach;?></div><?php if($showFrontQr):?><img class="qr" src="<?=e($qr)?>" alt="QR Code"><?php endif;?><?php if($showMotto):?><div class="motto"><?=e((string)setting('doc_motto',''))?></div><?php endif;?></section>
<section class="card back back-card <?=$active?'':'inactive'?>"><div class="left"><img src="<?=e($logo)?>" alt="Brasão BAMAB"><b>BAMAB</b><small>BANDA AMARAL BRASIL</small></div><div class="ribbon"></div><div class="back-title <?=$backTitleClass?>"><?=e($backTitle)?></div><div class="back-content"><div class="notice <?=$backNoticeClass?>"><h3>INFORMAÇÕES IMPORTANTES</h3><p><?=nl2br(e($backNotice))?></p></div><?php if($signatures):?><div class="signs"><?php foreach($signatures as $sig):?><div class="sig"><small><?=e((string)$sig)?></small><div></div></div><?php endforeach;?></div><?php endif;?><div class="back-bottom"><div class="back-valid"><small><?=e((string)setting('doc_validity_label','VALIDADE'))?></small><strong><?=e($valid)?></strong></div><?php if($showBackQr):?><img class="back-qr" src="<?=e($qr)?>" alt="QR Code"><?php endif;?></div></div></section>
<div class="buttons"><button type="button" onclick="bamabPrintCard('both')">IMPRIMIR FRENTE E VERSO</button><button type="button" onclick="bamabPrintCard('front')">SOMENTE FRENTE</button><button type="button" onclick="bamabPrintCard('back')">SOMENTE VERSO</button></div><div class="note">Carteira padrão ID-1: <strong>85,60 × 53,98 mm</strong>. Imprima em <strong>100%</strong>, tamanho real, sem ajustar à página e com margens <strong>nenhuma</strong>.</div></div><script>
function bamabAutoFit(el,minPx){if(!el)return;let size=parseFloat(getComputedStyle(el).fontSize)||12;let tries=0;while((el.scrollHeight>el.clientHeight+1||el.scrollWidth>el.clientWidth+1)&&size>minPx&&tries<40){size-=.35;el.style.fontSize=size+'px';tries++;}}
function bamabFitCard(){document.querySelectorAll('.title,.student-name-band strong,.back-title,.field strong,.notice p,.sig small,.motto').forEach(el=>bamabAutoFit(el,5.2));}
function bamabPrintCard(mode){document.body.classList.remove('print-front','print-back');if(mode==='front')document.body.classList.add('print-front');if(mode==='back')document.body.classList.add('print-back');bamabFitCard();setTimeout(()=>window.print(),60);}
window.addEventListener('load',bamabFitCard);window.addEventListener('afterprint',()=>document.body.classList.remove('print-front','print-back'));
</script></body></html><?php
}
